1	import { useState } from 'react';
2	import { useMutation, useQueryClient } from '@tanstack/react-query';
3	import { HttpError, postJson } from '../../api/http';
4	import { useSubmitOnce } from '../../query/useSubmitOnce';
5	import { HomeMain } from '../../slots/defs/homeMain';
6	import { useCurrentSheet, useCurrentUser } from '../../session/session';
7	import { poolsKey } from '../pools/pools';
8	import { ratesKey } from '../rates/rates';
9	import { type Settings, settingsKey, useSettings } from './settings';
10	
11	const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
12	
13	/** The standing rule each action keeps while its permission is blank. */
14	const STANDING_PERMS: Record<(typeof PERM_ACTIONS)[number], string> = {
15	  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
16	};
17	
18	type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;
19	
20	type Key = 'clerk-limit' | 'floor' | 'terms' | 'terms-A' | 'terms-B' | 'terms-C' | 'grace-A' | 'grace-B' | 'grace-C' | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'cap' | 'proof-threshold' | 'proof-threshold-A' | 'proof-threshold-B' | 'proof-threshold-C' | 'note-threshold' | 'grace-days' | 'entry-date' | 'pot' | 'alert-threshold' | 'parent' | 'fiscal-start-month' | PermKey;
21	
22	const GRADES = ['A', 'B', 'C'] as const;
23	
24	/** The settings that carry a figure: each is saved from a from-date (blank for the sheet's today). */
25	type DatedKey = Exclude<Key, 'policy-date' | 'period-numbering-from' | 'grace-days' | 'entry-date' | 'pot' | 'alert-threshold' | 'parent' | 'fiscal-start-month' | PermKey>;
26	
27	const NO_FROM: Record<DatedKey, string> = { 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'late-pct': '', cap: '', 'proof-threshold': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'note-threshold': '' };
28	
29	const isDated = (k: Key): k is DatedKey => k in NO_FROM;
30	
31	// The sheet's settings in force, and the form that changes them: the clerk limit (blank for none),
32	// the floor (blank for its default), the terms in days (blank for 14), each grade's own terms (blank
33	// for the sheet's terms), each grade's grace days (blank for none: whole days after its due-by a claim of
34	// a person of the grade on its date is not yet overdue, and its late charge counts from) and the late percent (blank for
35	// 0.00), the policy date rounding turns on (blank for the sheet's today) and the date claims opened
36	// are numbered per period from (blank for off), and the cap on a person's due-total (blank for none), and the proof threshold above which a claim's due needs a proof to be settled or approved (blank for none), and each grade's own proof threshold, which a claim of a person of the grade on its date takes instead (blank for none: the sheet's), and the note threshold above which a claim's due needs a note to be opened (blank for none). Saving changes the setting last touched, so a field left blank does not clear the others.
37	// Each setting that carries a figure is saved from its from-date (blank for the sheet's today), and shows
38	// the value in force on the sheet's today; the policy date and period numbering date are not dated.
39	// The permission matrix gives, for each action, the roles that may take it, comma separated (blank keeps
40	// the standing rule, shown as the placeholder); it is not dated. The grace days (blank for off, not
41	// dated) are the whole days after its to-date an open period is closed when the sheet's today moves.
42	// The entry date (blank for off, not dated) is the default date of a new claim in place of the sheet's today.
43	// The pot (blank for none, not dated) is shared out among each balanced pool's members by their shares.
44	// The alert threshold (blank for off, not dated) is the due-total above which a person a change takes there
45	// raises an ALERT in the audit file.
46	// The parent (a sheet id, blank for none, not dated) is the sheet whose rates a grade with no rate in force on a
47	// date takes, then its parent's, up to three levels up.
48	// The fiscal start month (1 to 12, not dated) is the month a fiscal year starts in; 1 unless set.
49	function SheetSettings() {
50	  const [user] = useCurrentUser();
51	  const [sheet] = useCurrentSheet();
52	  const settings = useSettings(sheet);
53	  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '', 'proof-threshold': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'note-threshold': '', 'grace-days': '', 'entry-date': '', pot: '', 'alert-threshold': '', parent: '', 'fiscal-start-month': '',
54	    'perm-open': '', 'perm-settle': '', 'perm-void': '', 'perm-reassign': '', 'perm-close': '', 'perm-reopen': '' });
55	  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
56	  const [key, setKey] = useState<Key>('clerk-limit');
57	  const queryClient = useQueryClient();
58	
59	  const save = useMutation({
60	    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
61	      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
62	    onSuccess: async (_, { key }) => {
63	      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
64	      if (key === 'pot') await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
65	      if (key === 'parent') await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
66	      setValues((v) => ({ ...v, [key]: '' }));
67	      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
68	    },
69	  });
70	  const submit = useSubmitOnce(save);
71	
72	  const field = (k: Key, placeholder: string, inputMode: 'decimal' | 'text' = 'decimal') => (
73	    <input
74	      data-testid={`setting-${k}`}
75	      placeholder={placeholder}
76	      inputMode={inputMode}
77	      value={values[k]}
78	      onFocus={() => setKey(k)}
79	      onChange={(e) => {
80	        setValues({ ...values, [k]: e.target.value });
81	        setKey(k);
82	        save.reset();
83	      }}
84	    />
85	  );
86	
87	  const from = (k: DatedKey) => (
88	    <input
89	      data-testid={`setting-${k}-from`}
90	      placeholder="From YYYY-MM-DD (blank for today)"
91	      value={froms[k]}
92	      onFocus={() => setKey(k)}
93	      onChange={(e) => {
94	        setFroms({ ...froms, [k]: e.target.value });
95	        setKey(k);
96	        save.reset();
97	      }}
98	    />
99	  );
100	
101	  return (
102	    <section data-testid="settings">
103	      <h2>Settings</h2>
104	      <form
105	        data-testid="settings-form"
106	        onSubmit={(e) => {
107	          e.preventDefault();
108	          submit({ key, value: values[key], from: isDated(key) ? froms[key] : '' });
109	        }}
110	      >
111	        Clerk limit <strong data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</strong>{' '}
112	        {field('clerk-limit', 'Clerk limit (blank for none)')}{' '}{from('clerk-limit')}{' '}
113	        Floor <strong data-testid="setting-floor-current">{settings.data?.floor ?? ''}</strong>{' '}
114	        {field('floor', 'Floor (blank for 1.00)')}{' '}{from('floor')}{' '}
115	        Terms <strong data-testid="setting-terms-current">{settings.data?.terms ?? ''}</strong>{' '}
116	        {field('terms', 'Terms in days (blank for 14)')}{' '}{from('terms')}{' '}
117	        {GRADES.map((g) => (
118	          <span key={g}>
119	            Terms {g} <strong data-testid={`setting-terms-${g}-current`}>{settings.data?.gradeTerms?.[g] ?? ''}</strong>{' '}
120	            {field(`terms-${g}`, `Terms for grade ${g} (blank for the sheet's)`)}{' '}{from(`terms-${g}`)}{' '}
121	          </span>
122	        ))}
123	        {GRADES.map((g) => (
124	          <span key={g}>
125	            Grace {g} <strong data-testid={`setting-grace-${g}-current`}>{settings.data?.gradeGrace?.[g] ?? ''}</strong>{' '}
126	            {field(`grace-${g}`, `Grace days for grade ${g} (blank for none)`)}{' '}{from(`grace-${g}`)}{' '}
127	          </span>
128	        ))}
129	        Late percent <strong data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</strong>{' '}
130	        {field('late-pct', 'Late percent (blank for 0.00)')}{' '}{from('late-pct')}{' '}
131	        Policy date <strong data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</strong>{' '}
132	        {field('policy-date', 'Policy date YYYY-MM-DD (blank for today)', 'text')}{' '}
133	        Period numbering from <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>{' '}
134	        {field('period-numbering-from', 'Period numbering from YYYY-MM-DD (blank for off)', 'text')}{' '}
135	        Cap <strong data-testid="setting-cap-current">{settings.data?.cap ?? ''}</strong>{' '}
136	        {field('cap', 'Cap (blank for none)')}{' '}{from('cap')}{' '}
137	        Proof threshold <strong data-testid="setting-proof-threshold-current">{settings.data?.proofThreshold ?? ''}</strong>{' '}
138	        {field('proof-threshold', 'Proof threshold (blank for none)')}{' '}{from('proof-threshold')}{' '}
139	        {GRADES.map((g) => (
140	          <span key={g}>
141	            Proof threshold {g} <strong data-testid={`setting-proof-threshold-${g}-current`}>{settings.data?.gradeProofThreshold?.[g] ?? ''}</strong>{' '}
142	            {field(`proof-threshold-${g}`, `Proof threshold for grade ${g} (blank for the sheet's)`)}{' '}{from(`proof-threshold-${g}`)}{' '}
143	          </span>
144	        ))}
145	        Note threshold <strong data-testid="setting-note-threshold-current">{settings.data?.noteThreshold ?? ''}</strong>{' '}
146	        {field('note-threshold', 'Note threshold (blank for none)')}{' '}{from('note-threshold')}{' '}
147	        Grace days <strong data-testid="setting-grace-days-current">{settings.data?.graceDays ?? ''}</strong>{' '}
148	        {field('grace-days', 'Grace days (blank for off)')}{' '}
149	        Entry date <strong data-testid="setting-entry-date-current">{settings.data?.entryDate ?? ''}</strong>{' '}
150	        {field('entry-date', 'Entry date YYYY-MM-DD (blank for off)', 'text')}{' '}
151	        Pot <strong data-testid="setting-pot-current">{settings.data?.pot ?? ''}</strong>{' '}
152	        {field('pot', 'Pot (blank for none)')}{' '}
153	        Alert threshold <strong data-testid="setting-alert-threshold-current">{settings.data?.alertThreshold ?? ''}</strong>{' '}
154	        {field('alert-threshold', 'Alert threshold (blank for off)')}{' '}
155	        Parent <strong data-testid="setting-parent-current">{settings.data?.parent ?? ''}</strong>{' '}
156	        {field('parent', 'Parent sheet id (blank for none)', 'text')}{' '}
157	        Fiscal start month <strong data-testid="setting-fiscal-start-month-current">{settings.data?.fiscalStartMonth ?? ''}</strong>{' '}
158	        {field('fiscal-start-month', 'Fiscal start month (1 to 12)')}{' '}
159	        {PERM_ACTIONS.map((a) => (
160	          <span key={a}>
161	            May {a} <strong data-testid={`setting-perm-${a}-current`}>{settings.data?.perms?.[a] ?? ''}</strong>{' '}
162	            {field(`perm-${a}`, `Roles that may ${a}, comma separated (blank for ${STANDING_PERMS[a]})`, 'text')}{' '}
163	          </span>
164	        ))}
165	        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
166	          Save settings
167	        </button>
168	        {save.isError && (
169	          <span data-testid="settings-error" role="alert">
170	            {' '}
171	            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The settings were refused.'}
172	          </span>
173	        )}
174	      </form>
175	    </section>
176	  );
177	}
178	
179	export const contribution = HomeMain.fill({ order: 48, Component: SheetSettings });
